import { Resend } from "resend";
import { and, eq } from "drizzle-orm";
import { getDb } from "@/db";
import { emailNotifications } from "@/db/schema";

// App-level transactional email via Resend, kept entirely separate from Supabase Auth's own
// emails (verification links, password resets) — those are generated by Supabase and only need
// Resend configured as Supabase's SMTP provider in the Supabase dashboard, a manual dashboard step
// documented in the handover rather than code here. This file only ever sends the "audit ready"
// notification today, using the "kind" column so a future promotional send path can never share
// a dedupe row with account/report notifications (an explicit requirement: keep them separate).
const FROM_NOTIFICATIONS = process.env.RESEND_FROM_NOTIFICATIONS || "Improvexus <onboarding@resend.dev>";
const FROM_PROMOTIONAL = process.env.RESEND_FROM_PROMOTIONAL || FROM_NOTIFICATIONS;

function client() {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) throw new Error("RESEND_API_KEY is not configured.");
  return new Resend(apiKey);
}

async function alreadySent(auditId: string, kind: string) {
  const db = getDb();
  const [row] = await db.select({ status: emailNotifications.status }).from(emailNotifications)
    .where(and(eq(emailNotifications.auditId, auditId), eq(emailNotifications.kind, kind))).limit(1);
  return row?.status === "sent";
}

async function recordAttempt(params: { auditId: string | null; userEmail: string; kind: string; status: "sent" | "failed"; providerMessageId?: string | null; lastError?: string | null }) {
  const db = getDb();
  const existing = params.auditId
    ? await db.select({ id: emailNotifications.id }).from(emailNotifications).where(and(eq(emailNotifications.auditId, params.auditId), eq(emailNotifications.kind, params.kind))).limit(1)
    : [];
  if (existing[0]) {
    await db.update(emailNotifications).set({ status: params.status, providerMessageId: params.providerMessageId, lastError: params.lastError ?? null, updatedAt: new Date() }).where(eq(emailNotifications.id, existing[0].id));
  } else {
    await db.insert(emailNotifications).values({ auditId: params.auditId, userEmail: params.userEmail, kind: params.kind, status: params.status, providerMessageId: params.providerMessageId, lastError: params.lastError ?? null });
  }
}

// Shared card shell for every app-sent email (table-based layout, inline styles only) so audit
// notifications and any future promotional send look like the same product as the Supabase auth
// emails (confirm signup / reset password) configured separately in the Supabase dashboard. Kept
// as plain functions rather than a template engine since there are only two callers.
function emailShell(bodyRows: string) {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f5;padding:40px 16px;font-family:Arial,Helvetica,sans-serif;">
    <tr><td align="center">
      <table role="presentation" width="100%" style="max-width:480px;background-color:#ffffff;border:1px solid #e5e5e8;border-radius:12px;padding:32px;">
        <tr><td style="font-size:15px;font-weight:700;color:#0b0b0d;letter-spacing:-0.2px;padding-bottom:24px;">Improvexus</td></tr>
        ${bodyRows}
      </table>
    </td></tr>
  </table>`;
}

function auditReadyHtml(profileName: string, reportUrl: string) {
  return emailShell(`
    <tr><td style="font-size:20px;font-weight:700;color:#0b0b0d;padding-bottom:12px;">Your audit is ready</td></tr>
    <tr><td style="font-size:14px;line-height:1.6;color:#4a4a52;padding-bottom:24px;">Your Upwork profile audit${profileName ? ` for <strong>${profileName}</strong>` : ""} is done. Sign in to see the full breakdown and download your PDF or Word report.</td></tr>
    <tr><td style="padding-bottom:24px;"><a href="${reportUrl}" style="display:inline-block;background-color:#0b0b0d;color:#ffffff;padding:12px 28px;border-radius:999px;text-decoration:none;font-size:14px;font-weight:700;">View my audit</a></td></tr>
    <tr><td style="font-size:12px;color:#9a9aa3;">Improvexus — Profile Growth &amp; Positioning Audit</td></tr>
  `);
}

// Sends (or retries) the "your audit is ready" notification for one audit. Two independent layers
// of duplicate protection, because they guard against two different crash points:
//
// 1. alreadySent()'s check below is our own bookkeeping: if a PRIOR CALL already recorded
//    status="sent" in emailNotifications, skip Resend entirely. This is what makes a normal retry
//    (e.g. a delivery job reclaimed after a stale "processing" lock) cheap and side-effect-free
//    once we know the send definitely happened and we definitely know it.
// 2. The `idempotencyKey` below covers the gap #1 can't see: Resend accepts the send (the email is
//    genuinely queued/delivered) but the worker crashes or the connection drops before
//    recordAttempt()'s write lands — so our own table still says "no successful send on record"
//    and a retry reaches this function again. Without an idempotency key, that retry would call
//    resend.emails.send() a second time and genuinely double-email the customer. With it, Resend
//    itself recognizes the duplicate key within its dedupe window and returns the ORIGINAL send's
//    result instead of dispatching a second email — so even the "our DB write never happened"
//    crash case can't produce two emails. The key is deterministic (tied 1:1 to this audit) so
//    every retry of the same logical send reuses the same key; a different audit always gets a
//    different key, so this can never suppress a legitimately different email.
export async function sendAuditReadyEmail(params: { auditId: string; userEmail: string; profileName: string; reportUrl: string }) {
  if (await alreadySent(params.auditId, "audit_ready")) return { sent: true, skipped: true as const };
  try {
    const resend = client();
    const { data, error } = await resend.emails.send(
      {
        from: FROM_NOTIFICATIONS,
        to: params.userEmail,
        subject: "Your Improvexus audit is ready",
        html: auditReadyHtml(params.profileName, params.reportUrl),
      },
      { idempotencyKey: `audit-ready:${params.auditId}` },
    );
    if (error) throw new Error(error.message);
    await recordAttempt({ auditId: params.auditId, userEmail: params.userEmail, kind: "audit_ready", status: "sent", providerMessageId: data?.id });
    return { sent: true, skipped: false as const };
  } catch (error) {
    const message = error instanceof Error ? error.message : "The notification email could not be sent.";
    await recordAttempt({ auditId: params.auditId, userEmail: params.userEmail, kind: "audit_ready", status: "failed", lastError: message });
    return { sent: false, error: message };
  }
}

// Infrastructure for a future promotional send path — deliberately never called from the audit
// generation flow, and always recorded under kind "promotional" so it can never collide with, or
// be mistaken for, an account/report notification's dedupe row.
export async function sendPromotionalEmail(params: { userEmail: string; subject: string; html: string }) {
  const resend = client();
  const { data, error } = await resend.emails.send({ from: FROM_PROMOTIONAL, to: params.userEmail, subject: params.subject, html: params.html });
  if (error) {
    await recordAttempt({ auditId: null, userEmail: params.userEmail, kind: "promotional", status: "failed", lastError: error.message });
    throw new Error(error.message);
  }
  await recordAttempt({ auditId: null, userEmail: params.userEmail, kind: "promotional", status: "sent", providerMessageId: data?.id });
  return { sent: true };
}
